<script setup lang="ts">
import type {KabanCategory} from '~~/shared/types/kaban'
const props=defineProps<{categories:KabanCategory[];active:string;count:(category:KabanCategory)=>number}>()
const emit=defineEmits<{select:[id:string]}>()
const roots=computed(()=>props.categories.filter(category=>!category.parentId)),collapsed=ref<string[]>([])
const children=(id:string)=>props.categories.filter(category=>category.parentId===id)
function toggle(id:string){collapsed.value=collapsed.value.includes(id)?collapsed.value.filter(item=>item!==id):[...collapsed.value,id]}
</script>
<template><nav class="vault-nav category-folder-nav" aria-label="Категории Кабана"><div v-for="category in roots" :key="category.id"><div class="kaban-category-branch"><button :class="{selected:active===category.id}" @click="emit('select',category.id)"><span class="kaban-stage-dot" :style="{background:category.color}"/><span class="nav-category-name">{{category.name}}</span><span class="nav-count">{{count(category)}}</span></button><button v-if="children(category.id).length" class="kaban-category-toggle" :aria-label="`${collapsed.includes(category.id)?'Развернуть':'Свернуть'} ${category.name}`" :aria-expanded="!collapsed.includes(category.id)" @click="toggle(category.id)"><UIcon :name="collapsed.includes(category.id)?'i-lucide-chevron-right':'i-lucide-chevron-down'"/></button></div><div v-if="!collapsed.includes(category.id)" class="category-folder-children"><button v-for="child in children(category.id)" :key="child.id" :class="{selected:active===child.id}" @click="emit('select',child.id)"><span class="kaban-stage-dot" :style="{background:child.color}"/><span class="nav-category-name">{{child.name}}</span><span class="nav-count">{{count(child)}}</span></button></div></div><p v-if="!roots.length" class="folder-empty">Нет открытых категорий</p></nav></template>
<style scoped>.kaban-category-branch{display:flex;align-items:center;min-width:0}.kaban-category-branch>button:first-child{flex:1;min-width:0}.kaban-category-branch>.kaban-category-toggle{width:26px;padding:8px 5px;flex-shrink:0}.kaban-category-branch .nav-category-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}</style>
